//! Temporary measurement of validator compilation cost. Deleted before commit.

use std::path::PathBuf;
use std::time::Instant;

use serde_json::Value;

fn spec_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("spec")
}

#[test]
fn measure_validator_compilation() {
    let revisions = ["2024-11-05", "2025-03-26", "2025-06-18", "2025-11-25", "2026-07-28"];
    let start = Instant::now();
    let mut count = 0usize;
    for revision in revisions {
        let text = std::fs::read_to_string(spec_dir().join(revision).join("schema.json"))
            .expect("schema");
        let mut document: Value = serde_json::from_str(&text).expect("parse");
        let container = if document.get("$defs").is_some() { "$defs" } else { "definitions" };
        let names: Vec<String> = document
            .get(container)
            .and_then(Value::as_object)
            .map(|map| map.keys().cloned().collect())
            .unwrap_or_default();
        for name in names {
            let root = document.as_object_mut().expect("object");
            root.insert(
                "$ref".to_owned(),
                Value::String(format!("#/{container}/{name}")),
            );
            let compiled = jsonschema::validator_for(&document).expect("compile");
            count += 1;
            std::hint::black_box(compiled);
        }
    }
    println!("compiled {count} validators in {:?}", start.elapsed());
}

