/// each `proptest!` block has no temporary whose lifetime the expansion would
/// have to get right.
fn values(revision: &str, definition: &str) -> BoxedStrategy<Value> {
    let defs = defs_for(revision);
    value_for_def(definition, &defs).unwrap_or_else(|| {
